import math

def is_power(num, base):
    if num <= 0:
        return False
    if num == 1:
        # Base must be > 1 for the definition to be useful, but we check for A >= 2 later
        return True if base > 1 else False

    # Check if num is a power of base
    while num > 1:
        if num % base != 0:
            return False
        num //= base
    return True

solutions = []
primes = [2, 3, 5, 7]
N_max = 25
A_limit = 15 # Limit for the exponent A to keep computation feasible initially

for p in primes:
    for n in range(1, N_max + 1):

        # Iterate over possible exponents A >= 2
        for A in range(2, A_limit + 1):
            p_A = p**A

            # Condition 1: m^2 = p^A - n > 0
            m_squared = p_A - n

            if m_squared <= 0:
                # Since p^A is increasing, further A will also yield m^2 <= 0 if this happens
                if A > 2: 
                    break # Optimization: stop increasing A for this (p, n)
                continue 

            # Check if m_squared is a perfect square
            m = int(math.isqrt(m_squared))

            if m * m == m_squared and m >= 1:
                # Found potential m

                # Condition 2: m + n^2 must be a power of p, B >= 2
                target = m + n**2

                if target <= p:
                    # B must be at least 2, so target must be >= p^2
                    continue

                if is_power(target, p):
                    # Since target >= p^2, the exponent B must be >= 2
                    solutions.append((m, n, p))

print("Solutions found (m, n, p):")
for sol in solutions:
    print(sol)
print(f"Total solutions found: {len(solutions)}")
